			SaveSettings("QuestDojo", false)
		else
			local y = checkboat()
			if not y then
				local P = CFrame.new(-16204.0810546875, 9.0863618850708, 479.2259521484375)
				if (P.Position - t.Character.HumanoidRootPart.Position).Magnitude > 8 then
