						G.Hit = CFrame.new(P.CFrame.Position, J)
						G.Target = Y
					end
				until not Y
					or not Y.Parent
					or not Settings["Auto Quest Dragon Hunter"]
					or y
					or (Y:GetAttribute("AlreadyDestroyedClient"))
					or tick() - H >= 15
			end
		end
	end
end
