function DetectGolem()
	for b, b in ipairs(game.workspace.Enemies:GetChildren()) do
		if
			b.Name == "Lava Golem"
			and (IsMobAlive(b))
			and t:DistanceFromCharacter(b.HumanoidRootPart.Position) <= 1500
		then
			return b
		end
	end
end
