function CheckPosnearRock(b, s)
	local X, g = 1 / 0
	local R = 0
	for l, S in next, b, nil do
		local b = Vector3.new(S.X, 0, S.Z)
		local I = (Vector3.new(s.Position.X, 0, s.Position.Z) - b).Magnitude
		if X > I then
			X, g, R = I, S, l
		end
	end
	return g, R
end
