function hasCooldownChanged(R)
	local m, l = R:GetAttributes(), g
	if not l then
		g = R:GetAttributes()
	end
	for R, l in next, m, nil do
		if
			(
				string.find(R, "GunCooldown")
				or (string.find(R, "MeleeCooldown"))
				or (string.find(R, "SwordCooldown"))
				or (string.find(R, "BloxFruitCooldown"))
			) and l > 0
		then
			if g[R] ~= l then
				g = m
				return true
			end
		end
	end
	return false
end
