							if Settings["Select Weapon"] == "Blox Fruit" then
								toTarget(f.HumanoidRootPart.CFrame * CFrame.new(-7, 20, 0))
							else
								toTarget(f.HumanoidRootPart.CFrame * CFrame.new(7, 20, 0))
